dir.commands:
		&FormShowing;




declare @rangeFrom smalldatetime, @rangeTo smalldatetime
select @rangeFrom = ngay_gh1, @rangeTo = ngay_gh2 from dmstt
select 'this._$d1 = $func.formatStringToDate(''' + convert(char(8), @rangeFrom, 112) + ''');this._$d2 = $func.formatStringToDate(''' + convert(char(8), @rangeTo, 112) + ''');active$VoucherFilter$(this);' as message
return




		&XMLWhenFilterClosing;




select cast(@tu_ngay as smalldatetime) as date_from, cast(@den_ngay as smalldatetime) as date_to
declare @$size int
select @$size = [length] from syscolumns where id = object_id('wrkgl') and name = 'so_ct'
exec zrs_VoucherBookUpdate @tu_ngay, @den_ngay, @ma_quyen, @ma_ct, @ma_quyen_blank, @ma_dvcs, 1, @@language, @@userID, @@admin






				/* <flatten type="Javascript"> */
var f = this, id = f.get_id(), v = f._language == 'v', p = f.getItemValue('period'), y = f.getItemValue('year');
var o1 = f.getItemValue('tu_ngay', null, null, true), o2 = f.getItemValue('den_ngay', null, null, true);
var d1 = new Date(o1.getFullYear(), o1.getMonth(), o1.getDate());
var d2 = new Date(o2.getFullYear(), o2.getMonth(), o2.getDate());
var e = (v ? 'Trường <span class="Highlight">Từ/đến ngày</span> giá trị nhập không hợp lệ.' : 'Field <span class="Highlight">Date from/to</span> has invalid value.');

if (d1 > d2 || d1 < f._$d1 || d1 > f._$d2 || d2 < f._$d1 || d2 > f._$d2 || (!f._hiddenPeriod && (d2.getMonth() != d1.getMonth() || d1.getFullYear() != d2.getFullYear()) || (f._hiddenPeriod && ((d2.getFullYear() - d1.getFullYear()) * 12 + d2.getMonth() - d1.getMonth() + 1) > 24)) {
	$func.hideWait(id);
	$message.show(e, String.format('$find(\'{0}\').getItem(\'tu_ngay\').focus()', id));
	f._checked = false;
}
/* </flatten> */

script.text:
			&OutlineEntry;

function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete);
	f.setReferenceKeyFilter('ma_quyen');
	var d = new Date();
	f.setItemValues('period, year', [d.getMonth() + 1, d.getFullYear()]);
	setDefaul$LastDateMonth(f);

	changeLookupReadonly(f, 'ma_ct', true);
	changeLookupReadonly(f, 'ma_dvcs', true);

	&FormActive;
}
/* <flatten type="Javascript"> */
function close$VoucherFilter$(f) {try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid;
			g._ma_quyen = f.getItemValue('ma_quyen');
			g._ma_ct = f.getItemValue('ma_ct');
			g._ma_quyen_blank = f.getItemValue('ma_quyen_blank');
			g._ma_dvcs = f.getItemValue('ma_dvcs');
			g._dFrom = f.getItemValue('tu_ngay');
			g._dTo = f.getItemValue('den_ngay');

			var dFrom = f.getItem('tu_ngay').value, dTo = f.getItem('den_ngay').value;
			g._alterTitle = [null, [['%d1', dFrom, true], ['%d2', dTo, true]]];
			break;
		default:
			break;
	}
}
function setItemLive(t1, t2, type) {
	if (type) {if (t2.live) {t1.disabled = false; t1.focus(); return t1;}}
		else {if (t1.live) {t2.disabled = false; t2.focus(); return t2;}}
	return null;
}
function setItemDisable(f, c, v) {
	var a = c.split(',');
	for (var i = 0; i < a.length; i++) {
		var o = f.getItem($func.trim(a[i]));
		if (o.a) $common.setVisible(o.a, !v);
		o.disabled = v;
	}
}

function setItemFormVisible(f, name, v) {
	var o = f.getItem(name);
	$common.setVisible(f.getItem(name).parentNode.parentNode.parentNode, v);
	if (o.field.Type == 'Decimal') o.value = 0;
	else o.value = '';
}

function onChange$Period(o) {setDefaul$LastDateMonth(o.parentForm);}
function onChange$Year(o) {
	var f = o.parentForm;
	setDefaul$LastDateMonth(f);
	f.live(f.getItem('tu_ngay'));
}
function onChange$DateFrom(o) {
	var f = o.parentForm;
	f.setReferenceKeyFilter('ma_quyen');
}
function setDefaul$LastDateMonth(f) {
	var p = f.getItemValue('period'), y = f.getItemValue('year');
	var d = new Date(y, p - 1, 1);
	var lastDayOfMonth = new Date(d.getFullYear(), d.getMonth() + 1, 0);
	f.setItemValues('tu_ngay, den_ngay', [d, lastDayOfMonth]);
	f.setReferenceKeyFilter('ma_quyen');
}

function setObjectFilterHidden(f, c, b) {
	var o = f.getItem(c);
	o.field.AllowNulls = !b;
	if (b) {
		var grandNode = o.parentNode.parentNode;
		Sys.UI.DomElement.addCssClass(grandNode, 'Required');
		Sys.UI.DomElement.addCssClass(grandNode, f._id);
	}
	if (b) {if (!f._controlFocus) f._controlFocus = o;}
	else $common.setVisible(o.parentNode.parentNode.parentNode, false);
}
/* </flatten> */
